const commander = require('../');

// The default value of a positive/negated pair must not depend on the order the options are added.

describe('negated option default does not depend on order', () => {
  test.each([
    ['negated first', (p) => p.option('--no-pepper').option('--pepper')],
    ['positive first', (p) => p.option('--pepper').option('--no-pepper')],
  ])('when both defined with no default then undefined (%s)', (_name, add) => {
    const program = new commander.Command();
    add(program);
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toBeUndefined();
  });

  test('when lone negated then default true', () => {
    const program = new commander.Command();
    program.option('--no-pepper');
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toBe(true);
  });

  test.each([
    [
      'negated first',
      (p) =>
        p.option('--no-pepper', 'remove pepper', 'plain').option('--pepper'),
    ],
    [
      'positive first',
      (p) =>
        p.option('--pepper').option('--no-pepper', 'remove pepper', 'plain'),
    ],
  ])('when negated has explicit default then used (%s)', (_name, add) => {
    const program = new commander.Command();
    add(program);
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toBe('plain');
  });
});
